import boto3

def extract_receipt_fields(receipt_image):
    textract = boto3.client('textract')
    response = textract.analyze_document(
        Document={'Bytes': receipt_image},
        FeatureTypes=['FORMS']
    )
    merchant = None
    tax = None
    total = None
    items = []
    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            if block['Text'] == 'Merchant':
                merchant = block['ValueDetection']['Text']
            elif block['Text'] == 'Tax':
                tax = float(block['ValueDetection']['Text'])
            elif block['Text'] == 'Total':
                total = float(block['ValueDetection']['Text'])
        elif block['BlockType'] == 'LINE':
            items.append(block['Text'])
    return {'merchant': merchant, 'tax': tax, 'total': total, 'items': items}

import json

def normalize_expense(expense):
    normalized_expense = {
        'vendor': expense['vendor'],
        'date': expense['date'],
        'total': expense['total'],
        'line_items': expense['line_items'],
        'merchant': expense['merchant'],
        'tax': expense['tax'],
        'items': expense['items']
    }
    return json.dumps(normalized_expense, indent=2)

def validate_document_fields(document):
    required_fields = ['vendor', 'date', 'total', 'line_items', 'merchant', 'tax', 'items']
    for field in required_fields:
        if field not in document:
            raise ValueError(f'Missing required field: {field}')
    if document['total'] <= 0:
        raise ValueError('Total must be greater than zero')
    return True

